import {waferAt,stages} from './process-model.js';
import {t,sources} from './places.js';
export function mountProcess(container,onArea){
const steps=[
 ['metrology',t('Oblea preparada','Prepared wafer'),t('El sustrato de silicio es la base. Aquí ampliamos solo una sección para seguir cómo cambia una capa.','The silicon substrate is the base. We magnify one section to follow changes in a single layer.')],
 ['deposition',t('Depositar una película','Deposit a film'),t('Se añade material sobre la superficie. El material y la técnica dependen de la estructura que se quiere fabricar.','Material is added to the surface. The material and method depend on the structure being made.')],
 ['lithography',t('Aplicar resina y hornear','Coat resist and bake'),t('Un equipo de recubrimiento aplica resina fotosensible y se acondiciona la película. Es un equipo distinto del escáner de exposición.','A coating tool applies photosensitive resist and conditions the film. This is separate from the exposure scanner.')],
 ['lithography',t('Exponer el patrón','Expose the pattern'),t('La luz modifica químicamente zonas de la resina. Todavía no se ha grabado el material de debajo. El dibujo muestra resina positiva.','Light chemically changes areas of the resist. The underlying material has not yet been etched. This example uses positive resist.')],
 ['lithography',t('Hornear y revelar','Bake and develop'),t('Tras el tratamiento correspondiente, el revelador elimina las zonas expuestas de la resina positiva. Se abren ventanas sobre la película.','After the appropriate treatment, developer removes exposed areas of positive resist, opening windows over the film.')],
 ['etch',t('Transferir por grabado','Transfer by etching'),t('El grabado retira la película en las ventanas abiertas. La resina protege las zonas que deben permanecer.','Etching removes film through the open windows. Resist protects the areas that must remain.')],
 ['etch',t('Retirar resina y limpiar','Strip resist and clean'),t('Se retira la máscara temporal de resina y se limpian residuos. El patrón queda en el material de la película.','The temporary resist mask is stripped and residues cleaned. The pattern remains in the film material.')],
 ['metrology',t('Medir e inspeccionar','Measure and inspect'),t('Se comprueban dimensiones, alineación y defectos. Hay controles en distintos puntos del proceso; aquí se resume uno.','Dimensions, alignment and defects are checked. Controls occur at different points; this shows one representative check.')],
 ['deposition',t('Repetir con otras operaciones','Repeat with other operations'),t('Este patrón no es todavía un chip. Muchas secuencias forman dispositivos y conexiones. Según el proceso intervienen dopado, tratamientos térmicos y pulido CMP; no se representan sus recetas aquí.','This pattern is not yet a chip. Many sequences build devices and connections. Depending on the process, doping, thermal treatment and CMP polishing are involved; their recipes are not modeled here.')],
 ['test',t('Prueba eléctrica en oblea','Electrical wafer probe'),t('Se comprueban circuitos antes de separarlos. La medición permite identificar unidades válidas y defectuosas; el dibujo no presupone un rendimiento real.','Circuits are tested before separation. Measurements identify working and defective dies; no actual yield is assumed here.')],
 ['packaging',t('Separar los chips','Separate the dies'),t('La oblea se divide en chips individuales. El método y el orden de ciertas operaciones cambian según el tipo de encapsulado.','The wafer is divided into individual dies. The method and order of some operations vary with the packaging approach.')],
 ['packaging',t('Encapsular e interconectar','Package and interconnect'),t('Uno o varios chips se conectan con un soporte y una protección adecuados. Lógica y memoria pueden integrarse en sistemas avanzados; esta sección es esquemática.','One or more dies are connected to an appropriate support and protection. Logic and memory can be integrated into advanced systems; this section is schematic.')],
 ['test',t('Probar el conjunto','Test the assembly'),t('El conjunto se verifica antes de su uso. Pruebas e integración no convierten automáticamente el producto en un sistema apto para el espacio.','The assembly is verified before use. Testing and integration do not automatically make the product a space-qualified system.')]
];let step=0,timer=null;
container.innerHTML=`<div class="process-title"><div><span class="eyebrow">${t('DE LA OBLEA AL CHIP · PROCESO INDUSTRIAL REPRESENTATIVO','FROM WAFER TO CHIP · REPRESENTATIVE INDUSTRIAL PROCESS')}</span><h2>${t('Mira lo que cambia en el material.','Watch the material change.')}</h2></div><button id="process-play">▶ ${t('Recorrer proceso','Play process')}</button></div><p class="process-scope">${t('Ejemplo de transferencia de patrón con resina positiva. No es la receta de Terafab, ni una simulación de tiempos, rendimiento o producción. Los colores y espesores están ampliados para explicar el cambio.','Positive-resist pattern-transfer example. This is not the Terafab recipe or a simulation of timing, yield or output. Colors and thicknesses are exaggerated to explain the changes.')}</p><div class="process-layout"><div><div class="process-steps" role="group" aria-label="${t('Pasos de fabricación','Manufacturing steps')}">${steps.map((s,i)=>`<button data-step="${i}" aria-pressed="${i===0}"><b>${String(i+1).padStart(2,'0')}</b>${s[1]}</button>`).join('')}</div></div><div class="wafer-panel"><div class="wafer-key"><span>■ ${t('Silicio','Silicon')}</span><span>■ ${t('Película','Film')}</span><span>■ ${t('Resina temporal','Temporary resist')}</span></div><svg id="wafer-section" viewBox="0 0 600 250" role="img"></svg><div aria-live="polite"><span class="eyebrow" id="process-number"></span><h3 id="process-name"></h3><p id="process-description"></p></div><div class="process-actions"><button id="process-prev" aria-label="${t('Paso anterior','Previous step')}">←</button><button id="process-area">${t('Ver zona relacionada en 3D','Show related 3D area')} ↗</button><button id="process-next" aria-label="${t('Paso siguiente','Next step')}">→</button></div><p class="process-note">${t('El carro FOUP de la maqueta representa transporte protegido. Su circuito animado no reproduce esta secuencia de fabricación ni un trazado confirmado.','The model FOUP carrier represents protected transport. Its animated loop does not reproduce this manufacturing sequence or a confirmed layout.')}</p></div></div><div class="process-sources"><a href="https://www.sec.gov/Archives/edgar/data/937966/000093796622000011/a2021asmlannualreportifr.htm" target="_blank" rel="noreferrer">ASML · ${t('exposición → revelado → grabado','exposure → development → etching')} ↗</a><a href="${sources.lam}" target="_blank" rel="noreferrer">Lam Research · ${t('deposición y limpieza','deposition and cleaning')} ↗</a><a href="https://www.appliedmaterials.com/us/en/semiconductor/products/shape.html" target="_blank" rel="noreferrer">Applied Materials · CMP ↗</a><a href="https://www.intel.com/content/www/us/en/newsroom/news/intel-foundry/intels-us-advanced-packaging-enables-next-generation-ai-semiconductors.html" target="_blank" rel="noreferrer">Intel · ${t('encapsulado avanzado','advanced packaging')} ↗</a></div>`;
const $=s=>container.querySelector(s);
function draw(){const state=waferAt(step);let svg='';const rect=(x,y,w,h,color)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${color}"/>`;
if(step<10){svg+=rect(70,155,450,65,'#789baa');for(let i=0;i<9;i++){if(state.film[i])svg+=rect(70+i*50,125,50,30,'#a7e0cf');if(state.resist[i])svg+=rect(70+i*50,95,50,30,state.exposed&&i%3===1?'#f5d794':'#b9adfa');if(state.exposed&&i%3===1)svg+=`<path d="M${95+i*50} 20V88" stroke="#ffde88" stroke-width="5"/><path d="M${89+i*50} 78l6 10 6-10" fill="none" stroke="#ffde88" stroke-width="3"/>`;}
if(state.multilayer){for(let j=0;j<3;j++){svg+=rect(70,65-j*18,450,12,'#647c98');for(let k=0;k<5;k++)svg+=rect(90+k*90,65-j*18,35,12,j%2?'#e9b58e':'#a7e0cf');}svg+=`<text x="295" y="25" text-anchor="middle" fill="#cedde3" font-size="15">${t('Capas y conexiones esquemáticas','Schematic layers and connections')}</text>`;}
if(state.inspected)svg+=`<path d="M70 232H520M70 227v10M520 227v10" stroke="#e6d59b"/>`;
if(state.probed)for(let i=0;i<5;i++)svg+=`<path d="M${125+i*75} 10l-12 25" stroke="#e6d59b" stroke-width="3"/>`;
}else if(!state.packaged){for(let i=0;i<5;i++){svg+=rect(55+i*105,130,70,60,'#789baa');svg+=rect(55+i*105,110,70,20,'#a7e0cf');}svg+=`<text x="300" y="65" text-anchor="middle" fill="#cedde3" font-size="17">${t('Chips separados · vista ampliada','Separate dies · magnified view')}</text>`;}else{svg+=rect(70,170,460,25,'#c6af89')+rect(180,115,100,45,'#a7e0cf')+rect(305,120,90,40,'#b9adfa');for(let i=0;i<12;i++)svg+=`<circle cx="${100+i*36}" cy="212" r="7" fill="#96adbd"/>`;for(const x of [200,220,240,260,320,340,360,380])svg+=rect(x,161,6,9,'#eac58f');svg+=`<path d="M145 155V85H435V155" fill="none" stroke="#91afbc" stroke-width="10"/><text x="300" y="45" text-anchor="middle" fill="#cedde3" font-size="17">${state.finalTest?t('Verificación eléctrica del conjunto','Assembly electrical verification'):t('Soporte + conexiones + chips + protección','Support + connections + dies + protection')}</text>`;}
$('#wafer-section').innerHTML=svg;$('#wafer-section').setAttribute('aria-label',steps[step][1]+': '+steps[step][2]);$('#process-number').textContent=`${String(step+1).padStart(2,'0')} / ${steps.length}`;$('#process-name').textContent=steps[step][1];$('#process-description').textContent=steps[step][2];$('#process-prev').disabled=step===0;$('#process-next').disabled=step===steps.length-1;container.querySelectorAll('[data-step]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.step===step)));}
function stop(){clearInterval(timer);timer=null;$('#process-play').textContent='▶ '+t('Recorrer proceso','Play process');}function go(n){stop();step=n;draw();if(innerWidth<760)container.querySelector('.wafer-panel').scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}container.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>go(+b.dataset.step));$('#process-prev').onclick=()=>go(Math.max(0,step-1));$('#process-next').onclick=()=>go(Math.min(steps.length-1,step+1));$('#process-area').onclick=()=>{onArea(steps[step][0]);document.querySelector('#scene').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'});};$('#process-play').onclick=()=>{if(timer){stop();return;}if(step===stages.length-1)step=0;draw();$('#process-play').textContent='Ⅱ '+t('Pausar','Pause');timer=setInterval(()=>{if(document.hidden)return;step++;draw();if(step===stages.length-1)stop();},5000);};draw();
}
